    ["02-11"] = {steps={[1]={node="Ventormenta"}, [2]={npc="Ayudante de alguacil Rainer", tgt="Ayudante de alguacil Rainer"}, [3]={npc="Granjero Cejade", tgt="Granjero Cejade"}, [4]={npc="Verna Cejade", tgt="Verna Cejade"}, [5]={npc="Verna Cejade", tgt="Verna Cejade"}, [6]={hint="Verna Cejade de los Páramos de Poniente quiere que le lleves 8 puñados de avena.", tag="Opcional"}, [7]={npc="Granjero Saldean", tgt="Granjero Saldean"}, [8]={npc="Salma Saldean", tgt="Salma Saldean"}, [9]={npc="Ozwin Piñón de Hierro", tgt="Ozwin Piñón de Hierro"}, [10]={npc="Gryan Mantorrecio", tgt="Gryan Mantorrecio"}, [11]={npc="Gryan Mantorrecio", tgt="Gryan Mantorrecio"}, [12]={node="Colina del Centinela"}, [13]={npc="Explorador Galiaan", tgt="Explorador Galiaan"}, [14]={npc="Alba Lunaclara", tgt="Alba Lunaclara"}, [15]={npc="Alba Lunaclara", tgt="Alba Lunaclara"}, [16]={hint="Utiliza el kit de muestra de agua de pozo para recoger muestras de los pozos que hay en la Finca de Jansen y la Granja de Molsen."}, [17]={hint="El granjero Cejade quiere que recuperes el reloj de bolsillo que dejó olvidado en el guardarropa de su granja en la plantación de calabazas del Oeste.", desc="Ajustando la cámara puedes recogerlo desde fuera."}, [18]={hint="Alba Lunaclara quiere que reúnas 7 branquias de múrloc de Playa Larga en las costas de Páramos de Poniente."}, [19]={npc="Granjero Cejade", tgt="Granjero Cejade"}, [20]={hint="El granjero Saldean quiere que mates a 20 vigías de la cosecha."}, [21]={npc="Verna Cejade", tgt="Verna Cejade"}, [22]={npc="Granjero Saldean", tgt="Granjero Saldean"}, [23]={npc="Alba Lunaclara", tgt="Alba Lunaclara"}, [24]={npc="Alba Lunaclara", tgt="Alba Lunaclara"}, [25]={npc="Alba Lunaclara", tgt="Alba Lunaclara"}, [26]={hint="Mata a 4 cavadores kóbold en la Mina de Jango y a 6 mineros Zarparrío en la Mina de la Costa del Oro."}, [27]={hint="Gryan Mantorrecio quiere que mates a 15 tramperos Defias y a 15 contrabandistas Defias. Cuando lo hayas hecho vuelve a verle en la Colina del Centinela."}, [28]={npc="Gryan Mantorrecio", tgt="Gryan Mantorrecio"}, [29]={npc="Gryan Mantorrecio", tgt="Gryan Mantorrecio"}, [30]={npc="Gryan Mantorrecio", tgt="Gryan Mantorrecio", tag="Opcional"}, [31]={hint="Lleva 15 pañuelos de cuero rojo al explorador Galiaan en la Colina del Centinela."}, [32]={hint="Ozwin Piñón de Hierro, en la Finca de Saldean, quiere que consigas 14 isorresortes de gólem y 5 giroestabilizadores de cosechador."}, [33]={hint="Gryan Mantorrecio quiere que mates a 15 saqueadores Defias y a 15 despojadores Defias. Cuando lo hayas hecho vuelve a verle en la Colina del Centinela.", tag="Opcional", desc="Es un desvío solo para esto; no hay otros objetivos cerca. Si tienes prisa, sáltala."}, [34]={npc="Alba Lunaclara", tgt="Alba Lunaclara"}, [35]={npc="Explorador Galiaan", tgt="Explorador Galiaan"}, [36]={npc="Gryan Mantorrecio", tgt="Gryan Mantorrecio", tag="Opcional"}, [37]={npc="Ozwin Piñón de Hierro", tgt="Ozwin Piñón de Hierro"}, [39]={npc="Baros Alexston", tgt="Baros Alexston"}, [40]={npc="Baros Alexston", tgt="Baros Alexston"}, [41]={npc="Brandur Martiyerro", tgt="Brandur Martiyerro"}, [42]={npc="Tiza Forjabatalla", tgt="Tiza Forjabatalla"}, [43]={npc="Escrito sobre divinidad", npcObj=true, desc="Haz clic derecho en Escrito sobre divinidad en tu bolsa para empezar la misión."}, [44]={npc="Tiza Forjabatalla", tgt="Tiza Forjabatalla"}, [45]={npc="Tiza Forjabatalla", tgt="Tiza Forjabatalla"}, [46]={npc="John Turner", tgt="John Turner"}, [47]={npc="John Turner", tgt="John Turner"}, [48]={npc="John Turner", tgt="John Turner", desc="Si tienes menos de 10 Paños de lino, cómpralos en la casa de subastas. Suelen ser baratos."}, [49]={npc="John Turner", tgt="John Turner"}, [50]={npc="Tiza Forjabatalla", tgt="Tiza Forjabatalla"}, [51]={npc="Tiza Forjabatalla", tgt="Tiza Forjabatalla"}, [52]={npc="Muiredon Forjabatalla", tgt="Muiredon Forjabatalla"}, [53]={npc="Muiredon Forjabatalla", tgt="Muiredon Forjabatalla"}, [54]={npc="Borgus Mano de Acero", tgt="Borgus Mano de Acero"}, [55]={npc="Grimand Elmore", tgt="Grimand Elmore"}, [56]={npc="Furen Barbalarga", tgt="Furen Barbalarga"}, [57]={text="Ve al Distrito de los Enanos de Ventormenta y toma el Tranvía Subterráneo a Forjaz."}, [58]={npc="Gnoarn", tgt="Gnoarn"}}},
    ["05-d1"] = {name="El Salón de Señores Feudales", entrance="Forjaz 27.63, 47.83", pickup="Acepta las misiones de la mazmorra al pasar por Dun Morogh y Loch Modan; así no tendrás que volver antes de entrar.", pickupS={{"Acepta las misiones de la mazmorra al pasar por Dun Morogh y Loch Modan; así no tendrás que volver antes de entrar"}}, steps={[1]={npc="Mapa de Hierro Negro", npcObj=true, tag="Requisito de mazmorra"}, [2]={npc="Videnterra Farsen", tgt="Videnterra Farsen", tag="Requisito de mazmorra"}, [3]={npc="Videnterra Farsen", tgt="Videnterra Farsen"}, [4]={npc="Afadra Muropardo", tgt="Afadra Muropardo"}, [5]={npc="Thom Birla", tgt="Thom Birla"}, [6]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [7]={text="Entrada: El Salón de Señores Feudales"}, [8]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [9]={hint="Mata 15 aparecidos iracundos y 10 almas atormentadas. Luego, ayuda al espíritu de Yunquemar a descansar en paz."}, [10]={hint="Reúne 8 reliquias de los enanos del Salón de Señores Feudales."}, [11]={hint="Entra en el Salón de Señores Feudales debajo de Antigua Forjaz y recupera la cabeza de Durgen Martillo de Endecha."}, [12]={npc="Treaty of Understanding", npcObj=true, desc="Haz clic derecho en Tratado del entendimiento en tu bolsa para empezar la misión. El jefe final lanza Miedo hacia el 35 % de salud. Limpia primero los esbirros y luego lleva al jefe a la sala anterior. Junto a quien da la misión hay una palanca. Tira de ella para abrir la puerta y sal en línea recta."}, [13]={npc="Thom Birla", tgt="Thom Birla"}, [14]={npc="Afadra Muropardo", tgt="Afadra Muropardo"}, [15]={npc="Rey Magni Barbabronce", tgt="Rey Magni Barbabronce"}, [16]={npc="Rey Magni Barbabronce", tgt="Rey Magni Barbabronce"}}},
