    [4731] = {n="Tortuga marina varada", d="Lleva la caja con símbolos extraños a Gwennyth Bly'Leggonde a Auberdine."},
    [4732] = {n="Tortuga marina varada", d="Lleva los restos de la tortuga marina a Gwennyth Bly'Leggonde a Auberdine."},
    [4733] = {n="Criatura marina varada", d="Lleva los huesos de la criatura marina a Gwennyth Bly'Leggonde a Auberdine."},
    [4740] = {n="SE BUSCA: ¡Viscoso!", d="Encuentra y mata al múrloc conocido como Viscoso. Se cree que la criatura está defendiendo el emplazamiento múrloc al sur de Auberdine, cerca del agua.\nInforma de la muerte de Viscoso a la centinela Glynda Nal'Shea, en Auberdine.", tgo={{"Viscoso"}}},
    [4761] = {n="Thundris Tejevientos", d="Ve a Auberdine y habla con Thundris Tejevientos."},
    [4762] = {n="El Río Fonroca", d="Viaja al norte de Auberdine hasta la primera cascada del Río Fonroca y recoge una muestra de agua.\nVuelve a Auberdine a buscar a Thundris Tejevientos con la muestra del Río Fonroca.", objs={"Cascada del Río Fonroca"}},
    [4763] = {n="La corrupción de los Bosque Negro", d="Llena el cuenco purificador vacío en la Poza de la Luna de Auberdine.\nRecoge una muestra de fruta, nueces y grano del campamento del norte de los fúrbolgs Bosque Negro.\nMezcla todo en el cuenco, llévalo al campamento norte y colócalo cerca de la hoguera más cercana al Río Fonroca; así convocarás al sátiro corruptor.\nCoge el dije de corrupción y llévaselo a Thundris Tejevientos a Auberdine.", objs={"Bolsa demoníaca de Xabraxxis"}},
    [4811] = {n="El cristal rojo", d="Viaja al este de Auberdine y busca un gran cristal rojo en la zona montañosa que hay al este de Costa Oscura. Vuelve a Auberdine e informa de lo que has encontrado a la centinela Glynda Nal'Shea.", objs={"Cristal rojo misterioso"}},
    [4812] = {n="Agua en cascada", d="Llena el tubo de agua vacío en la Poza de la Luna de Auberdine y luego examina el cristal rojo a lo largo de la pared montañosa oriental de Costa Oscura.", objs={"Poza de la Luna de Auberdine"}},
    [4813] = {n="Los trozos del interior", d="Vuelve a Auberdine e informa de lo que has averiguado a la centinela Glynda Nal'Shea."},
    [4842] = {n="Fuentes extrañas", d="Sigue las indicaciones de Donova Cubilnevado y vuelve a informarle."},
    [4861] = {n="Lechúcico salvaje iracundo", d="Localiza el campamento arrasado y los suministros de Jaron Tallapiedras en la parte sur de Cuna del Invierno."},
    [4863] = {n="Lechúcico salvaje iracundo", d="Encuentra el carro destrozado de Jaron Tallapiedras."},
    [4864] = {n="Lechúcico salvaje iracundo", d="Recoge de la nieve los Suministros de Jaron y encuentra al lechúcico salvaje que robó el amuleto del que te habló Jaron.\nLleva los Suministros de Jaron y el Amuleto de plumas azules a Jaron Tallapiedras en el refugio de Cuna del Invierno.", tgo={{}, {"Lechubestia enloquecida", "Lechubestia lunadón", "Lechubestia rabiosa", "Guardia de Elune"}}, objs={"Suministros de Jaron"}},
    [4901] = {n="Guardianes del altar", d="Protege a Ranshalla mientras intenta reactivar el Altar de Elune. Informa sobre tus descubrimientos a Erelas Cieloámbar de Aldea Rut'theran."},
    [4902] = {n="Lechúcico salvaje de Elune", d="Habla con el archidruida Fandral Corzocelada en Darnassus."},
    [4906] = {n="Más corrupción", d="Eridan Vientoazul de Frondavil quiere que mates a 8 clamainfernos Fuego de Jade, 8 traidores Fuego de Jade, 8 timadores Fuego de Jade y a Xavaric. Vuelve con Eridan cuando lo hayas hecho.", tgo={{"Clamainferno Fuego de Jade"}, {"Traidor Fuego de Jade"}, {"Timador Fuego de Jade"}, {"Xavaric"}}},
    [4971] = {n="Una cuestión de tiempo", d="Utiliza el desplazador temporal junto a uno de los silos de Andorhal y saca a la luz los parásitos temporales.\nMata a 15 parásitos temporales y devuélvele el desplazador temporal a Cromi en la posada de Andorhal, en las Tierras de la Peste del Oeste.", tgo={{"Parásito temporal"}}},
    [4984] = {n="La naturaleza también sufre", d="Destruye 8 lobos malsanos y regresa con Mulgris Río Hondo en El Tormento, en las Tierras de la Peste del Oeste.", tgo={{"Lobo malsano"}}},
    [4985] = {n="La naturaleza también sufre", d="Destruye 8 pardos malsanos y regresa con Mulgris Río Hondo en El Tormento, en las Tierras de la Peste del Oeste.", tgo={{"Oso pardo malsano"}}},
    [4986] = {n="Rama de roble con inscripciones", d="Según la magia con la que está encantada La rama de roble con inscripciones, el siguiente paso del druida tauren debía ser su entrega al Círculo Cenarion en Darnassus. Pide ayuda a uno de los druidas que encontrarás allí."},
    [5021] = {n="Más vale tarde que nunca", d="Entre lamentos, la mujer fantasmal recordaba tener que entregar un paquete. Según ella estaba junto a su caballo. No puedes entender dónde está el caballo o dónde había que entregar el paquete."},
    [5022] = {n="Más vale tarde que nunca", d="Consulta con los agentes reales de Ventormenta para averiguar el paradero de una tal Emma Piedra Mácula. Suele haber un oficial del censo en el Ayuntamiento."},
    [5048] = {n="El buen carácter de Emma", d="Encuentra a la Vieja Emma en Ventormenta y descubre si realmente es Emma Piedra Mácula. Si lo es, quizás quiera el paquete que Janice Piedra Mácula hizo para ella."},
    [5050] = {n="Talismán de buena suerte", d="Devuelve a Janice Piedra Mácula en las Tierras de la Peste del Oeste su Medio talismán de buena suerte."},
    [5066] = {n="Un llamamiento a las armas: las Tierras de la Peste", d="Busca al comandante Ashlam Puñovalor. Su campamento base se encuentra en Campamento del Orvallo, al norte de las Montañas de Alterac."},
    [5082] = {n="La amenaza de los Nevada", d="Donova Cubilnevado de Cuna del Invierno quiere que mates 8 abrecaminos Nevada, 8 vigías del cubil Nevada y 8 totémicos Nevada.", tgo={{"Abrecaminos Nevada"}, {"Vigía del cubil Nevada"}, {"Totémico Nevada"}}},
    [5083] = {n="Aguardiente Nevada", d="Lleva el frasco vacío de aguardiente a Donova Cubilnevado de Cuna del Invierno."},
    [5084] = {n="Sucumbir a la corrupción", d="Busca una pista en el campamento fúrbolg Muertobosque en el norte de Frondavil."},
    [5085] = {n="Baba misteriosa", d="Informa sobre tus descubrimientos a Donova Cubilnevado."},
    [5092] = {n="Despejar el camino", d="Mata 10 despellejadores esqueléticos y 10 necrófagos esclavizantes en la Colina de las Penas.\nVuelve con el comandante Ashlam Puñovalor en el Campamento del Orvallo, en las Tierras de la Peste del Oeste.", tgo={{"Despellejador esquelético"}, {"Necrófago esclavizante"}}},
    [5097] = {n="Todas las atalayas", d="Con la antorcha de aviso, marca las atalayas de Andorhal. Tendrás que estar en la entrada de la atalaya para poder marcarla.\nCuando estén marcadas las cuatro atalayas devuelve la antorcha de aviso al comandante Ashlam Puñovalor del Campamento del Orvallo, en las Tierras de la Peste del Oeste.", tgo={{"Torre uno de Andorhal"}, {"Torre dos de Andorhal"}, {"Torre tres de Andorhal"}, {"Torre cuatro de Andorhal"}}},
    [5149] = {n="La muñeca de Pamela", d="Encuentra la muñeca de Pamela."},
    [5152] = {n="Tía Marlene", d="Habla con Marlene. Está al sur de las Ruinas de Andorhal."},
    [5153] = {n="Una extraña historiadora", d="Lleva la alianza de Joseph a Cromi.", objs={"Monumento de Joseph Rutagrana"}},
    [5154] = {n="Las Crónicas de Villa Darrow", d="Lleva el libro Crónicas de Villa Darrow a Cromi a Andorhal.", objs={"Libro enmohecido"}},
    [5155] = {n="Las fuerzas de Jaedenar", d="Entra en Jaedenar y mata a 4 canes Jaedenar, 4 guardianes Jaedenar, 6 adeptos Jaedenar y 6 cultores Jaedenar antes de volver con Greta Pezuñamusgo a Frondavil.", tgo={{"Can Jaedenar"}, {"Guardián Jaedenar"}, {"Adepto Jaedenar"}, {"Cultor Jaedenar"}}},
    [5156] = {n="Verificación de la corrupción", d="Busca y destruye a 2 bestias entrópicas y 2 horrores entrópicos a la vez que exploras la Cañada Gran Cicatriz. Cuando hayas comprobado si los cráteres del lugar aún contienen agua vil corrupta, vuelve con Taronn Plumarroja a Frondavil.", tgo={{"Bestia entrópica"}, {"Horror entrópico"}}},
    [5157] = {n="Recolección de agua corrupta", d="Lleva la cantimplora vacía a la Poza de la Luna que hay en el centro de Jaedenar y llénala antes de volver con Greta Pezuñamusgo a Frondavil.", objs={"La Poza de la Luna corrupta de Jaedenar"}},
    [5158] = {n="En busca de ayuda espiritual", d="Lleva el agua de la Poza de la Luna corrupta a Islen Vidente del Agua a Los Baldíos."},
    [5159] = {n="El agua purificada regresa a Frondavil", d="Lleva el agua de la Poza de la Luna purificada a Greta Pezuñamusgo en Frondavil."},
    [5168] = {n="Los héroes de Villa Darrow", d="Lleva el Tratado de Davil y el Escudo de Rutagrana a Carlin Rutagrana.", objs={"Tratado de Davil", "Escudo de Rutagrana"}},
    [5181] = {n="Los villanos de Villa Darrow", d="Lleva el cráneo de Horgus y la espada destrozada de Marduk a Carlin Rutagrana a la Capilla de la Esperanza de la Luz.", objs={"Cráneo de Horgus", "Espada destrozada de Marduk"}},
    [5210] = {n="Carlin, el hermano de Joseph", d="Lleva las Crónicas ampliadas de Villa Darrow a Carlin Rutagrana a las Tierras de la Peste del Este."},
    [5211] = {n="Los defensores de Villa Darrow", d="Libera a 15 espíritus de Villa Darrow y vuelve con Carlin Rutagrana.", tgo={{"Espíritu de Villa Darrow"}}},
    [5215] = {n="Las calderas de la Plaga", d="Habla con la suma sacerdotisa MacDonnell en el Alto del Orvallo, en las Tierras de la Peste del Oeste."},
    [5216] = {n="Objetivo: Campo de Piedramácula", d="Ve al Campo de Piedramácula en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Seguramente tendrá una llave para acceder a la caldera. Debes llevar contigo la Botella vacía del Campo de Piedramácula para obtener una muestra de los venenos utilizados en el interior de la caldera.", tgo={{"Señor de la caldera Garravil"}}},
    [5217] = {n="Regresa al Campamento del Orvallo", d="Lleva la Botella rellena del Campo de Piedramácula a la suma sacerdotisa MacDonnell en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."},
    [5219] = {n="Objetivo: Llanto de Dalson", d="Ve al Llanto de Dalson en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la botella vacía del Llanto de Dalson para obtener una muestra de los venenos utilizados en el interior de la caldera.", tgo={{"Señor de la caldera Molevolus"}}},
    [5220] = {n="Regresa al Campamento del Orvallo", d="Lleva la botella del Llanto de Dalson llena a la suma sacerdotisa MacDonnell en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."},
    [5222] = {n="Objetivo: El Tormento", d="Ve a El Tormento en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la Botella vacía de El Tormento para obtener una muestra de los venenos utilizados en el interior de la caldera.", tgo={{"Señor de la caldera Razarch"}}},
    [5223] = {n="Regresa al Campamento del Orvallo", d="Lleva la Botella llena de El Tormento a la suma sacerdotisa MacDonnell en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."},
    [5225] = {n="Objetivo: Gangrena de Gahrron", d="Ve a la Gangrena de Gahrron en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la Botella vacía de la Gangrena de Gahrron para obtener una muestra de los venenos utilizados en el interior de la caldera.", tgo={{"Señor de la caldera Iralma"}}},
    [5226] = {n="Regresa al Campamento del Orvallo", d="Lleva la botella llena de la Gangrena de Gahrron a la suma sacerdotisa MacDonnell en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."},
    [5238] = {n="¡Misión cumplida!"},
    [5241] = {n="Tío Carlin", d="Encuentra a Carlin Rutagrana."},
    [5244] = {n="Las Ruinas de Kel'Theril", d="Habla con Jaron Tallapiedras en Aldea Estrella Fugaz."},
    [5245] = {n="Espíritus condenados de Kel'Theril", d="Utiliza el pico de Gormir para encontrar los cuatro trozos de reliquia de los Altonato.", objs={"Trozo de reliquia de Altonato"}},
    [5246] = {n="Trozos del pasado", d="Encuentra las Sagradas escrituras de los Altonato del Templo de Zin-Malor en Azshara y tráelas para Aurora Clamacielos en la Torre del Paso Norte en las Tierras de la Peste del Este.", objs={"Sagradas escrituras de los Altonato"}},
    [5250] = {n="Estrella Fugaz", d="Encuentra la Aldea Estrella Fugaz en Cuna del Invierno y habla con Wynd Cazanoche."},
    [5261] = {n="Eagan Desollapelambres", d="Habla con Eagan Desollapelambres."},
    [5401] = {n="Comisión de El Alba Argenta"},
    [5541] = {n="Municiones para Estruendo", d="Lleva la munición de Estruendo a Hegnar Estruendo a Dun Morogh.", objs={"Cajón de munición"}},
    [5542] = {n="Perros demoníacos", d="Mata 20 cachorros de can de peste, 5 canes de peste y 5 canes de peste demenciados. Cuando hayas terminado tu tarea regresa con Tirion Vadín.", tgo={{"Cachorro de can de peste"}, {"Can de peste"}, {"Can de peste demenciado"}}},
    [5543] = {n="Cielos sangrientos", d="Mata 30 murcipestes y vuelve con Tirion Vadín.", tgo={{"Murcipeste"}}},
    [5544] = {n="Gusanos carroñeros", d="Busca las larvas y devoradores carroñeros de la zona. Mátalos y recoge su carne. Regresa con Tirion Vadín cuando tengas 15 trozos de carne de gusano carroñero.", tgo={{"Larva carroñera", "Devorador carroñero"}}},
    [5545] = {n="El cumplimiento del plazo", d="Lleva 8 fardos de madera a Raelen al Aserradero de la Vega del Este.", objs={"Fardo de madera"}},
    [5601] = {n="Pamela, mi hermana", d="Encuentra a Pamela Rutagrana en Villa Darrow."},
    [5713] = {n="Un tiro. Un muerto.", d="Protege a la centinela Aynasha y luego ve a Vallefresno, a la Atalaya de Maestra, y habla con Onaeya."},
    [5742] = {n="Redención", d="Escucha lo que Tirion Vadín tiene que contarte.", tgo={{"Tirión Vadín"}}},
    [5762] = {n="Hemet Nesingwary", d="Lleva el cajón de Kravel a Hemet Nesingwary en Tuercespina."},
    [5781] = {n="De recuerdos olvidados", d="Viaja a La Subgranja, en la sección más meridional de las Tierras de la Peste del Este, y recupera el Martillo de Taelan. Cuando hayas cumplido tu objetivo regresa con Tirion Vadín.", tgo={{"Mercutio Comerroña"}}},
    [5845] = {n="Del honor perdido", d="Viaja a Vallenorte, en la zona noreste de las Tierras de la Peste del Este, y recupera el Símbolo de Honor perdido. Cuando hayas cumplido tu objetivo regresa con Tirion Vadín.", objs={"Símbolo de Honor perdido"}},
    [5846] = {n="Del amor y la familia", d="Viaja a la isla de Castel Darrow, en la región sur del centro de las Tierras de la Peste. Allí, busca pistas sobre el paradero del cuadro."},
    [5848] = {n="Del amor y la familia", d="Viaja a Stratholme, en la zona norte de las Tierras de la Peste. En El Bastión Escarlata encontrarás el cuadro 'Del amor y la familia', oculto tras otra pintura que representa las lunas gemelas de nuestro mundo.\nDevuelve la pintura a Tirion Vadín.", objs={"Cuadro a medias"}},
    [5863] = {n="La Base Machacaduna", d="Andi Lynn de Gadgetzan quiere que destruyas la Base Machacaduna y para conseguirlo tendrás que matar 10 toscos Machacadunas, 10 déspotas Machacadunas y a Gor'marok el Devastador.", tgo={{"Tosco Machacaduna"}, {"Déspota Machacaduna"}, {"Gor'marok el Devastador"}}},
    [5903] = {n="Una Peste en la Cruzada", d="Utiliza el tarro de termitas vacío en los montones de termitas de las Tierras de la Peste del Este. Cuando hayas reunido 100 termitas de las Tierras de la Peste, vuelve con Nathaniel Dumah al Campamento del Orvallo en las Tierras de la Peste del Oeste.", objs={"Montículo grande de termitas"}},
    [5904] = {n="Una Peste en la Cruzada", d="Encuentra un lugar adecuado en el centro del Aserradero Crestanorte, en las Tierras de la Peste del Oeste, para colocar la barrica de termitas de las Tierras de la Peste."},
    [6001] = {n="Cuerpo y corazón", d="Utiliza el polvo de luna Cenarion en la piedra de lechúcico lunar de Auberdine para invocar a Garraluna. Luego tendrás que enfrentarte a Garraluna y ganar la fuerza física y de corazón que posee.\nCuando hayas acabado, vuelve a Darnassus y habla con Mathrengyl Garroso.", tgo={{"Espíritu de Garraluna"}}},
    [6004] = {n="Negocios inconclusos", d="Mata a 2 médicos Escarlata, 2 cazadores Escarlata, 2 magos Escarlata y 2 caballeros Escarlata antes de regresar con Kirsta Sombraprofunda en las Tierras de la Peste del Oeste.", tgo={{"Médico Escarlata"}, {"Cazador Escarlata"}, {"Mago Escarlata"}, {"Caballero Escarlata"}}},
    [6021] = {n="Zaeldarr el Marginado", d="Lleva la cabeza de Zaeldarr al custodio Alen a la Capilla de la Esperanza de la Luz.", tgo={{"Zaeldarr el Marginado"}}},
    [6023] = {n="Negocios inconclusos", d="Mata al montero Radley y al hidalgo Durgen antes de regresar con Kirsta Sombraprofunda en las Tierras de la Peste del Oeste.", tgo={{"Montero Radley"}, {"Hidalgo Durgen"}}},
    [6024] = {n="La súplica de Hameya", d="Mata al infiltrador Hameya. Usa su llave en el túmulo detrás de La Subgranja.", tgo={{"Infiltrado Hameya"}}},
    [6025] = {n="Negocios inconclusos", d="Entra en la Vega del Amparo y busca un punto elevado desde el que puedas ver la ciudad y calcular las fuerzas de la Cruzada Escarlata. Cuando lo hayas hecho regresa con Kirsta Sombraprofunda en las Tierras de la Peste del Oeste."},
    [6028] = {n="El informe Vista Eterna", d="Entrega el informe de Vista Eterna a la oficial Argenta Purocorazón en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."},
    [6030] = {n="El duque Nicolas Zverenhoff", d="Entrega el libro, \"Estudios sobre la Comunicación con los Espíritus\", al duque Nicolas Zverenhoff en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."},
    [6063] = {n="Domesticar la bestia", d="Utiliza la fusta de doma para domar a un rondador Tejemadera. Practica tus habilidades y después devuélvele la fusta de doma a Dazalar, que está en Dolanaar.", tgo={{"Rondador Tejemadera"}}},
    [6064] = {n="Domesticar la bestia", d="Usa la fusta de doma para domar a un jabalí del risco grande. Practica un poco y devuélvele la fusta a Grif Corazón Salvaje en Kharanos.", tgo={{"Jabalí del risco grande"}}},
    [6084] = {n="Domesticar la bestia", d="Usa la fusta de doma para domar un leopardo de las nieves. Practica un poco y devuélvele la fusta a Grif Corazón Salvaje en Kharanos.", tgo={{"Leopardo de las nieves"}}},
    [6085] = {n="Domesticar la bestia", d="Usa la fusta de doma para domar un oso zarpahelada. Practica un poco y devuélvele la fusta a Grif Corazón Salvaje en Kharanos.", tgo={{"Oso zarpahelada"}}},
    [6086] = {n="Domesticar la bestia", d="Habla con Belia Tronagranito en Forjaz."},
    [6101] = {n="Domesticar la bestia", d="Utiliza la fusta de doma para domar a un acechador sable de la noche. Practica tus habilidades y después devuélvele la fusta de doma a Dazalar, que está en Dolanaar.", tgo={{"Acechador sable de la noche"}}},
    [6102] = {n="Domesticar la bestia", d="Utiliza la fusta de doma para domar a un estridador estrígido. Practica tus habilidades y después devuélvele la fusta de doma a Dazalar, que está en Dolanaar.", tgo={{"Estridador estrígido"}}},
    [6103] = {n="Domesticar la bestia", d="Habla con Jocaste en el Enclave Cenarion de Darnassus."},
    [6134] = {n="La caza de ectoplasmas", d="Llévale 8 ectoplasmas y el cajón de imanes fantasmales a Hornizz Zumbala en Desolace.", tgo={{"Espectro centauro"}}},
    [6182] = {n="El primero y el último", d="Habla con Mathias Shaw en el Casco Antiguo, en Ventormenta. Vive en los Cuarteles."},
    [6183] = {n="Honra a los muertos", d="Vuelve a hablar con Mathias Shaw si quieres aceptar esta misión."},
    [6184] = {n="Flint Sombramás", d="Vete al Campamento del Orvallo en las Tierras de la Peste del Oeste y reúnete con tu contacto, Flint Sombramás."},
    [6185] = {n="Las pestes del este", d="Explora las Tierras de la Peste del Este en busca de pistas sobre el \"Clamañublo\" y los agentes perdidos del IV:7. Si encuentras alguna insignia del IV:7 llévasela a Flint Sombramás en el Campamento del Orvallo.", objs={"Restos humanos destrozados"}},
    [6341] = {n="Las presas de Teldrassil", d="Lleva la colección de Nessa a Vesprystus."},
    [6342] = {n="Vuelo a Auberdine", d="Compra un vuelo en hipogrifo hasta Auberdine al maestro de hipogrifos Vesprystus y lleva la colección de Nessa a Laird."},
    [6343] = {n="Regreso a Nessa", d="Lleva la respuesta de Laird a Nessa Cantosombrío."},
    [6344] = {n="Nessa Cantosombrío", d="Habla con Nessa Cantosombrío."},
    [6387] = {n="Estudiantes de honor", d="Llévale la lista de Brocks a Thorgrum Borrelson en Thelsamar."},
    [6388] = {n="Gryth Thurden", d="Lleva los picos honorarios a Gryth Thurden en Forjaz."},
    [6389] = {n="Una Peste en la Cruzada", d="Libera las termitas de las Tierras de la Peste en el Aserradero Crestanorte y luego vuelve con la barrica de termitas de las Tierras de la Peste a Nathaniel Dumah en el Campamento del Orvallo en las Tierras de la Peste del Oeste."},
    [6391] = {n="Vuela a Forjaz", d="Contrata un vuelo en grifo a Forjaz con el maestro de grifos Thorgrum Borrelson y llévale la lista de Brock a Golnir Dedorroca, en Forjaz."},
